// Runs ../docs/testdata/review.json (generated by tools/gen_review_testdata.py) against the Dart review logic,
// plus PGN import, the opening book and a full engine-free review of a game.
import 'dart:convert';
import 'dart:io';

import 'package:chess_app/core/board.dart';
import 'package:chess_app/core/game.dart';
import 'package:chess_app/core/pgn.dart';
import 'package:chess_app/core/pgn_import.dart';
import 'package:chess_app/review/classify.dart';
import 'package:chess_app/review/material.dart';
import 'package:chess_app/review/openings.dart';
import 'package:chess_app/review/review.dart';
import 'package:flutter_test/flutter_test.dart';

dynamic loadJson(String name) => jsonDecode(File('../docs/testdata/$name').readAsStringSync());

const tol = 0.01;

void main() {
  final data = loadJson('review.json');
  final config = ReviewConfig.fromJson(data['config'] as Map<String, dynamic>);

  group('win percent and accuracy', () {
    for (final c in data['winPercent']) {
      final score = EngineScore.fromJson(c['score'] as Map<String, dynamic>);
      test('win% of $score', () => expect(winPercent(score), closeTo(c['expect'] as num, tol)));
    }
    for (final c in data['moveAccuracy']) {
      test('accuracy for loss ${c['loss']}', () => expect(moveAccuracy((c['loss'] as num).toDouble()), closeTo(c['expect'] as num, tol)));
    }
    test('game accuracy mixes arithmetic and harmonic means', () {
      expect(gameAccuracy([]), 100);
      expect(gameAccuracy([100, 100]), closeTo(100, tol));
      // arithmetic 60, harmonic 2 / (1/100 + 1/20) = 33.33 -> 46.67
      expect(gameAccuracy([100, 20]), closeTo(46.6667, tol));
    });
  });

  group('classification', () {
    for (final c in data['classify']) {
      test(c['name'] as String, () {
        final r = classifyMove(PlyInput.fromJson(c['input'] as Map<String, dynamic>), config);
        final e = c['expect'] as Map<String, dynamic>;
        expect(r.label.name, e['label']);
        expect(r.loss, closeTo(e['loss'] as num, tol));
        expect(r.winBefore, closeTo(e['winBefore'] as num, tol));
        expect(r.winAfter, closeTo(e['winAfter'] as num, tol));
        expect(r.accuracy, closeTo(e['accuracy'] as num, tol));
      });
    }
  });

  group('sacrifice', () {
    for (final c in data['sacrifice']) {
      test(c['name'] as String, () {
        final board = Board.fromFen(c['fen'] as String)!;
        final pv = [for (final m in c['pv'] as List) m as String];
        expect(sacrificedValue(board, c['played'] as String, pv), (c['expect'] as num).toDouble());
      });
    }
  });

  group('game', () {
    for (final g in data['game']) {
      test(g['name'] as String, () {
        final labels = <String>[];
        final acc = {'w': <double>[], 'b': <double>[]};
        for (final p in g['plies']) {
          final r = classifyMove(PlyInput.fromJson(p['input'] as Map<String, dynamic>), config);
          labels.add(r.label.name);
          acc[p['mover']]!.add(r.accuracy);
        }
        final e = g['expect'] as Map<String, dynamic>;
        expect(labels, e['labels']);
        expect(gameAccuracy(acc['w']!), closeTo(e['accuracyWhite'] as num, tol));
        expect(gameAccuracy(acc['b']!), closeTo(e['accuracyBlack'] as num, tol));
      });
    }
  });

  group('PGN import', () {
    final cases = loadJson('pgn.json')['pgn_import_cases'];
    for (final c in cases) {
      test(c['name'] as String, () {
        final r = importPgn(c['pgn'] as String);
        expect([for (final h in r.game.history) h.san], c['san']);
        expect(r.result, c['result']);
        expect(r.error != null, c['error'] == true, reason: r.error);
        for (final e in (c['headers'] as Map<String, dynamic>? ?? {}).entries) {
          expect(r.headers[e.key], e.value);
        }
        if (c['startFen'] != null) expect(r.game.initial.toFen(), c['startFen']);
      });
    }
    test('a game written by toPgn can be read back', () {
      final g = Game();
      for (final m in ['e2e4', 'c7c5', 'g1f3', 'd7d6']) {
        g.makeMoveUci(m);
      }
      final back = importPgn(toPgn(g));
      expect(back.game.board.toFen(), g.board.toFen());
    });
  });

  group('opening book', () {
    final tsv = File('../docs/data/openings.tsv').readAsStringSync();
    late final OpeningBook book;
    setUpAll(() => book = OpeningBook.parse(tsv));

    test('loads thousands of openings', () => expect(book.size, greaterThan(3000)));

    test('Ruy Lopez is recognised, with transposition-proof keys', () {
      final g = Game();
      for (final san in ['e4', 'e5', 'Nf3', 'Nc6', 'Bb5']) {
        expect(g.makeMoveSan(san), isTrue);
      }
      expect(book.contains(g.board), isTrue);
      expect(book.nameOf(g.board)?.name, contains('Ruy Lopez'));
    });

    test('a random sideline is not in the book', () {
      final g = Game();
      for (final san in ['a4', 'h5', 'Ra3', 'Rh6']) {
        g.makeMoveSan(san);
      }
      expect(book.contains(g.board), isFalse);
    });

    test('the Flutter asset copy matches docs/data/openings.tsv', () {
      expect(File('assets/data/openings.tsv').readAsStringSync(), tsv);
    });
  });

  group('engine-free review of a whole game', () {
    test("fool's mate gets the expected labels from canned evaluations", () {
      final g = Game();
      for (final san in ['f3', 'e5', 'g4', 'Qh4#']) {
        g.makeMoveSan(san);
      }
      // Positions: start, after f3, after e5, after g4 (mate in 1 for Black), after Qh4# (finished).
      final evals = [
        const PositionEval([EngineLine('e2e4', EngineScore.cp(30)), EngineLine('d2d4', EngineScore.cp(28))]),
        const PositionEval([EngineLine('e7e5', EngineScore.cp(120)), EngineLine('d7d5', EngineScore.cp(100))]),
        const PositionEval([EngineLine('e2e4', EngineScore.cp(-100)), EngineLine('d2d4', EngineScore.cp(-105))]),
        const PositionEval([EngineLine('d8h4', EngineScore.mate(1), ['d8h4'])]),
        const PositionEval([]),
      ];
      final r = reviewGame(g, evals);
      expect([for (final p in r.plies) p.label], [MoveLabel.mistake, MoveLabel.best, MoveLabel.blunder, MoveLabel.best]);
      expect(r.plies[2].bestSan, 'e4');
      expect(r.accuracyBlack, greaterThan(r.accuracyWhite));
      expect(r.whiteWinChance.length, 5);
      expect(r.whiteWinChance.last, 0); // Black mated White
    });
  });
}
